{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/patterns/media-frame.json
    A picture in a fixed ratio that follows the theme. `src` is the picture of the light theme, `darkSrc` the one of the dark theme (without it the dark theme shows `src`). Without both it shows the built-in neutral placeholders (base64 data URIs, one light and one dark), so a page can be laid out before it has pictures; the placeholder stands in for a real `src` and is switched by the theme token. `ratio` comes from the recipe; the corners are the plain theme radius.
    Props (p): alt, src, darkSrc, ratio, className. -#}
{%- set k_PLACEHOLDER = {'light': 'data:image/svg+xml;base64,', 'dark': 'data:image/svg+xml;base64,'} -%}
{%- set v_alt = ui_def(p['alt'], none) -%}
{%- set v_src = ui_def(p['src'], none) -%}
{%- set v_darkSrc = ui_def(p['darkSrc'], none) -%}
{%- set v_ratio = ui_def(p['ratio'], '16/9') -%}
{%- set v_lightSrc = ui_coalesce([v_src, ui_at(k_PLACEHOLDER, 'light')]) -%}
{%- set v_nightSrc = ui_coalesce([v_darkSrc, v_src, ui_at(k_PLACEHOLDER, 'dark')]) -%}
{%- set c_1 -%}
  {{ ui_include('ui/image/image.html.j2', {'p': {'Src': ui_s(v_lightSrc), 'Alt': ui_s(v_alt), 'Class': 'absolute inset-0 size-full object-cover dark:hidden', 'Attrs': ui_attrs(['data-theme-src', 'light'])}}) }}
  {{ ui_include('ui/image/image.html.j2', {'p': {'Src': ui_s(v_nightSrc), 'Alt': ui_s(v_alt), 'Class': 'absolute inset-0 hidden size-full object-cover dark:block', 'Attrs': ui_attrs(['data-theme-src', 'dark'])}}) }}
{%- endset -%}
{{ ui_include('ui/box/box.html.j2', {'p': {'Class': ui_s(ui_cnv([ui_recipe('blocks/recipes/media-frame.variants.json', {'ratio': v_ratio}), ui_def(p['className'], '')])), 'Attrs': ui_attrs(['data-slot', 'media-frame', 'data-placeholder', ('false' if ui_t(v_src) else 'true')])}, 'children': c_1}) }}
